-- ── 0087_seed_drennia.sql ────────────────────────────────────────────────────
-- Seeds the 4 drennia_states and 151 drennia_districts.
-- Run AFTER 0087_drennia_district_map.sql.
--
-- support_json is seeded empty '{}' — the tick engine will populate it once
-- parties are assigned color_hex and the first tick fires.
-- You can also manually set it to { "party-uuid": 50, "party-uuid2": 50 } etc.
--
-- district_number maps 1-to-1 with the SVG data-district-id in DrenniaMap.tsx
-- State codes match the SVG data-state-id attributes.

BEGIN;

-- ── 1. States ──────────────────────────────────────────────────────────────
-- We link to pol_states by code where they exist (NULL if your pol_states use
-- different codes — that's fine, it's an optional FK).

INSERT INTO drennia_states (id, name, code, color_hint) VALUES
  ('11111111-0000-0000-0000-000000000001', 'Vale',  'VALE',  '#4B6382'),
  ('11111111-0000-0000-0000-000000000002', 'Crest', 'CREST', '#7B5FA5'),
  ('11111111-0000-0000-0000-000000000003', 'March', 'MARCH', '#4A7D5A'),
  ('11111111-0000-0000-0000-000000000004', 'Thorn', 'THORN', '#8A5A3A')
ON CONFLICT (code) DO NOTHING;

-- ── 2. Districts ───────────────────────────────────────────────────────────
